(function(){var WEEK=7*24*60*60*1000;var box=document.querySelector('.ocs-float');if(!box){return;}
var HIDDEN='ocs_float_hidden_'+(box.getAttribute('data-ocs-bar')||'x');function dismissed(){try{var until=parseInt(localStorage.getItem(HIDDEN),10);return until&&until>Date.now();}catch(e){return false;}}
if(dismissed()){box.remove();return;}
box.hidden=false;var video=null;var calm=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;function attach(){var src=box.getAttribute('data-ocs-float-src');if(video||!src||calm){return;}
video=document.createElement('video');video.className='ocs-float__video';video.muted=true;video.loop=true;video.playsInline=true;video.setAttribute('muted','');video.setAttribute('playsinline','');video.preload='auto';video.src=src;video.addEventListener('playing',function(){box.classList.add('is-playing');});video.addEventListener('pause',function(){box.classList.remove('is-playing');});box.querySelector('.ocs-float__open').append(video);play();}
function play(){if(!video){return;}
var promise=video.play();if(promise&&promise.catch){promise.catch(function(){});}}
function pause(){if(video&&!video.paused){video.pause();}}
function seen(){var rect=box.getBoundingClientRect();return rect.bottom>0&&rect.top<(window.innerHeight||0);}
function decide(){if(document.hidden||!seen()){pause();return;}
attach();play();}
box.querySelector('[data-ocs-float-close]').addEventListener('click',function(e){e.stopPropagation();try{localStorage.setItem(HIDDEN,String(Date.now()+WEEK));}catch(err){}
pause();box.remove();});document.addEventListener('visibilitychange',decide);addEventListener('scroll',decide,{passive:true});addEventListener('resize',decide,{passive:true});function begin(){if(window.requestIdleCallback){requestIdleCallback(decide,{timeout:2000});return;}
setTimeout(decide,600);}
if('complete'===document.readyState){begin();}else{addEventListener('load',begin);}}());